+    private String requiredFileName(String ruleDescription, boolean initialization) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
+        } catch (RuntimeException e) {
+            if (initialization) {
+                throw new StoreInitializationFailedException("Could not derive a rule violation file name", e);
