+                        throw new StoreInitializationFailedException(inspection.failureMessage());
+                    }
+                } else {
+                    repair(inspection);
+                }
+            }
+            if (!storedRulesFile.exists()) {
+                storedRules.createIfAbsent();
+            }
+        }
+        log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
+    }
+
+    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
+        if (constructorStrategy != null) {
+            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            return ignored -> UUID.randomUUID().toString();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::descriptionFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate RuleViolationFileNameStrategy configured by %s='%s' (a public no-argument constructor is required)",
+                    FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private File prepareStoreFolderAndIndex() {
+        Path folderPath = storeFolder.toPath();
+        try {
+            if (Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS)) {
+                if (!Files.isDirectory(folderPath)) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Cannot create rule store: %s is not a folder", storeFolder.getAbsolutePath()));
+                }
+            } else {
+                if (!storeCreationAllowed) {
+                    throw storeCreationDisabled();
+                }
+                Files.createDirectories(folderPath);
+            }
+
+            File index = new File(storeFolder, STORED_RULES_FILE_NAME);
+            Path indexPath = index.toPath();
+            if (Files.exists(indexPath, LinkOption.NOFOLLOW_LINKS)) {
+                if (!Files.isRegularFile(indexPath, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "The violation store index %s is not a regular file directly in the store folder",
+                            index.getAbsolutePath()));
+                }
+            } else if (!storeCreationAllowed) {
+                throw storeCreationDisabled();
+            }
+            return index;
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private StoreInitializationFailedException storeCreationDisabled() {
+        return new StoreInitializationFailedException(String.format(
+                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.find(rule.getDescription()) != null;
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        checkNotNull(rule);
+        checkNotNull(violations);
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            IndexEntry existing = storedRules.find(rule.getDescription());
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty() && existing != null) {
+                forget(existing);
+                return;
+            }
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                return;
+            }
+
+            String ruleFileName = existing == null
+                    ? requiredFileName(rule.getDescription(), false)
+                    : existing.fileName;
+            if (existing == null) {
+                validateNewEntry(ruleFileName);
+                write(violations, directPath(ruleFileName));
+                Properties updated = storedRules.copy();
+                updated.setProperty(ensureUnixLineBreaks(rule.getDescription()), ruleFileName);
+                try {
+                    storedRules.commit(updated);
+                } catch (RuntimeException e) {
+                    deletePathIfPossible(directPath(ruleFileName));
+                    throw e;
+                }
+            } else {
+                validateExistingWrite(existing.fileName);
+                write(violations, pathForName(existing.fileName));
+            }
+        }
+    }
+
+    private void forget(IndexEntry entry) {
+        if (!isShared(entry)) {
+            deleteNamedFile(entry.fileName);
+        }
+        Properties updated = storedRules.copy();
+        updated.remove(entry.ruleDescription);
+        storedRules.commit(updated);
+    }
+
+    private void validateNewEntry(String fileName) {
+        Path path = directPath(fileName);
+        if (path == null || Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store violations: derived file name '%s' is already occupied or is not directly in the store folder",
+                    fileName));
+        }
+        if (isRecordedByAnotherEntry(fileName) || isIndexPath(path)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store violations: derived file name '%s' is already used by the store index or another entry",
+                    fileName));
+        }
+    }
+
+    private void validateExistingWrite(String fileName) {
+        Path path = pathForName(fileName);
+        if (path == null || !leadsToDirectStoreFile(path) || isIndexPath(path)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store violations: file name '%s' does not lead to a regular file directly in the store folder",
+                    fileName));
+        }
+    }
+
+    private boolean isRecordedByAnotherEntry(String fileName) {
+        for (IndexEntry entry : storedRules.entries()) {
+            if (entry.fileName.equals(fileName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        if (ruleDetails == null) {
+            throw new StoreUpdateFailedException("Cannot store violations: invalid rule violation file name");
+        }
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8));
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String requiredFileName(String ruleDescription, boolean initialization) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
+        } catch (RuntimeException e) {
+            if (initialization) {
+                throw new StoreInitializationFailedException("Could not derive a rule violation file name", e);
+            }
+            throw e;
+        }
+        if (result == null || result.isEmpty()) {
+            String message = String.format("Rule violation file name strategy returned no name for rule '%s'", ruleDescription);
+            if (initialization) {
+                throw new StoreInitializationFailedException(message);
+            }
+            throw new StoreUpdateFailedException(message);
+        }
+        return result;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            IndexEntry entry = storedRules.find(rule.getDescription());
+            checkArgument(entry != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(entry.fileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (isOnlyCarriageOrLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private boolean isOnlyCarriageOrLineBreaks(String text) {
+        if (text.isEmpty()) {
+            return true;
+        }
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character != '\n' && character != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            Path path = pathForName(fileName);
+            if (path == null) {
+                throw new IOException("Invalid rule violation file name: " + fileName);
+            }
+            return new String(toByteArray(path.toFile()), UTF_8);
+        } catch (IOException | InvalidPathRuntimeException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private IntegrityInspection inspectIntegrity() {
+        List<InspectedEntry> entries = new ArrayList<>();
+        for (IndexEntry indexEntry : storedRules.entries()) {
+            String derivedName = requiredFileName(indexEntry.ruleDescription, true);
+            Path path = pathForName(indexEntry.fileName);
+            boolean broken = path == null || isIndexPath(path) || !Files.isRegularFile(path);
+            boolean resolved = false;
+            if (!broken) {
+                resolved = readLines(indexEntry.fileName).isEmpty();
+            }
+            entries.add(new InspectedEntry(indexEntry, derivedName, path, broken, resolved));
+        }
+
+        markShared(entries);
+        Map<String, Integer> derivedCounts = new HashMap<>();
+        for (InspectedEntry entry : entries) {
+            Integer count = derivedCounts.get(entry.derivedName);
+            derivedCounts.put(entry.derivedName, count == null ? 1 : count + 1);
+        }
+        Set<String> recordedNames = new HashSet<>();
+        for (IndexEntry entry : storedRules.entries()) {
+            recordedNames.add(entry.fileName);
+        }
+        for (InspectedEntry entry : entries) {
+            entry.misplaced = !entry.indexEntry.fileName.equals(entry.derivedName);
+            entry.colliding = derivedCounts.get(entry.derivedName) > 1;
+            if (entry.misplaced) {
+                Path derivedPath = directPath(entry.derivedName);
+                entry.occupied = derivedPath == null
+                        || Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS)
+                        || recordedNames.contains(entry.derivedName);
+            }
+        }
+        return new IntegrityInspection(entries, findUnownedFiles(entries));
+    }
+
+    private void markShared(List<InspectedEntry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                InspectedEntry left = entries.get(i);
+                InspectedEntry right = entries.get(j);
+                boolean sameName = left.indexEntry.fileName.equals(right.indexEntry.fileName);
+                boolean sameFile = left.path != null && right.path != null && !left.broken && !right.broken
+                        && sameFile(left.path, right.path);
+                if (sameName || sameFile) {
+                    left.shared = true;
+                    right.shared = true;
+                }
+            }
+        }
+    }
+
+    private List<String> findUnownedFiles(List<InspectedEntry> entries) {
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path file : files) {
+                if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS) || isIndexPath(file)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (InspectedEntry entry : entries) {
+                    if (!entry.broken && entry.path != null && sameFile(file, entry.path)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private void repair(IntegrityInspection inspection) {
+        Properties updated = storedRules.copy();
+        boolean changed = false;
+        for (InspectedEntry entry : inspection.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                updated.remove(entry.indexEntry.ruleDescription);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteNamedFile(entry.indexEntry.fileName);
+                updated.remove(entry.indexEntry.ruleDescription);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveNamedFile(entry.indexEntry.fileName, entry.derivedName);
+                updated.setProperty(entry.indexEntry.ruleDescription, entry.derivedName);
+                changed = true;
+            }
+        }
+        if (changed) {
+            storedRules.commit(updated);
+        }
+    }
+
+    private void moveNamedFile(String oldName, String newName) {
+        Path source = pathForName(oldName);
+        Path destination = directPath(newName);
+        if (source == null || destination == null) {
+            throw new StoreInitializationFailedException("Cannot repair an invalid rule violation file name");
+        }
+        try {
+            Path moveSource = Files.isSymbolicLink(source) ? source.toRealPath() : source;
+            Files.move(moveSource, destination);
+            if (Files.isSymbolicLink(source)) {
+                Files.deleteIfExists(source);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void deleteNamedFile(String fileName) {
+        Path path = pathForName(fileName);
+        if (path == null) {
+            throw new StoreUpdateFailedException("Cannot delete invalid rule violation file name '" + fileName + "'");
+        }
+        try {
+            if (isIndexPath(path)) {
+                throw new IOException("The rule violation file is the store index");
+            }
+            if (Files.isSymbolicLink(path)) {
+                Path target = path.toRealPath();
+                Files.deleteIfExists(target);
+                Files.deleteIfExists(path);
+            } else {
+                Files.deleteIfExists(path);
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private boolean isShared(IndexEntry entry) {
+        List<IndexEntry> entries = storedRules.entries();
+        Path path = pathForName(entry.fileName);
+        for (IndexEntry other : entries) {
+            if (other.ruleDescription.equals(entry.ruleDescription)) {
+                continue;
+            }
+            if (other.fileName.equals(entry.fileName)) {
+                return true;
+            }
+            Path otherPath = pathForName(other.fileName);
+            if (path != null && otherPath != null && Files.isRegularFile(path) && Files.isRegularFile(otherPath)
+                    && sameFile(path, otherPath)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private boolean leadsToDirectStoreFile(Path path) {
+        try {
+            if (path == null || !Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                return path != null && path.getParent() != null && path.getParent().toRealPath().equals(canonicalStoreFolder);
+            }
+            if (!Files.isRegularFile(path)) {
+                return false;
+            }
+            return path.toRealPath().getParent().equals(canonicalStoreFolder);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private Path pathForName(String name) {
+        try {
+            if (name == null) {
+                return null;
+            }
+            Path namePath = Paths.get(name);
+            if (namePath.isAbsolute() || namePath.getNameCount() != 1) {
+                return null;
+            }
+            return storeFolder.toPath().resolve(namePath);
+        } catch (RuntimeException e) {
+            return null;
+        }
+    }
+
+    private Path directPath(String name) {
+        return pathForName(name);
+    }
+
+    private boolean isIndexPath(Path path) {
+        if (path == null) {
+            return false;
+        }
+        try {
+            return Files.exists(path, LinkOption.NOFOLLOW_LINKS)
+                    && Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)
+                    && Files.isSameFile(path, storedRulesFile.toPath());
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private boolean sameFile(Path left, Path right) {
+        try {
+            return Files.isSameFile(left, right);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private void deletePathIfPossible(Path path) {
+        if (path == null) {
+            return;
+        }
+        try {
+            Files.deleteIfExists(path);
+        } catch (IOException ignored) {
+            // The original update failure is more useful to the caller.
+        }
+    }
+
+    private static String descriptionFileName(String description) {
+        String normalized = ensureUnixLineBreaks(description);
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(normalized);
+        String retainedWord = null;
+        while (matcher.find()) {
+            retainedWord = matcher.group(1);
+        }
+        String digest = sha256(normalized);
+        return (retainedWord == null ? "rule" : retainedWord) + "-" + digest;
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte valueByte : digest) {
+                result.append(String.format("%02x", valueByte & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private static String canonicalPath(File file) {
+        return canonicalPathObject(file).getPath();
+    }
+
+    private static File canonicalPathObject(File file) {
+        try {
+            return file.getCanonicalFile();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private enum IntegrityMode {
+        REPAIR, FAIL, IGNORE;
+
+        static IntegrityMode from(String value) {
+            if (INTEGRITY_REPAIR.equals(value)) {
+                return REPAIR;
+            }
+            if (INTEGRITY_FAIL.equals(value)) {
+                return FAIL;
+            }
+            if (INTEGRITY_IGNORE.equals(value)) {
+                return IGNORE;
+            }
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid %s='%s'; accepted values are '%s', '%s' and '%s'",
+                    INTEGRITY_PROPERTY_NAME, value, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE));
+        }
+    }
+
+    private static class IndexEntry {
+        private final String ruleDescription;
+        private final String fileName;
+
+        private IndexEntry(String ruleDescription, String fileName) {
+            this.ruleDescription = ruleDescription;
+            this.fileName = fileName;
+        }
+    }
+
+    private static class InspectedEntry {
+        private final IndexEntry indexEntry;
+        private final String derivedName;
+        private final Path path;
+        private final boolean broken;
+        private final boolean resolved;
+        private boolean shared;
+        private boolean misplaced;
+        private boolean colliding;
+        private boolean occupied;
+
+        private InspectedEntry(IndexEntry indexEntry, String derivedName, Path path, boolean broken, boolean resolved) {
+            this.indexEntry = indexEntry;
+            this.derivedName = derivedName;
+            this.path = path;
+            this.broken = broken;
+            this.resolved = resolved;
+        }
+    }
+
+    private class IntegrityInspection {
+        private final List<InspectedEntry> entries;
+        private final List<String> unownedFiles;
+
+        private IntegrityInspection(List<InspectedEntry> entries, List<String> unownedFiles) {
+            this.entries = entries;
+            this.unownedFiles = unownedFiles;
+        }
+
+        private boolean isHealthy() {
+            for (InspectedEntry entry : entries) {
+                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
+                    return false;
+                }
+            }
+            return unownedFiles.isEmpty();
+        }
+
+        private String failureMessage() {
+            StringBuilder result = new StringBuilder("Violation store integrity check failed");
+            appendEntries(result, "broken", entry -> entry.broken);
+            appendEntries(result, "resolved", entry -> entry.resolved);
+            appendEntries(result, "shared", entry -> entry.shared);
+            appendEntries(result, "misplaced", entry -> entry.misplaced);
+            appendEntries(result, "colliding", entry -> entry.colliding);
+            appendEntries(result, "occupied", entry -> entry.occupied);
+            if (!unownedFiles.isEmpty()) {
+                result.append("\nunowned files:");
+                for (String file : unownedFiles) {
+                    result.append("\n  ").append(file);
+                }
+            }
+            return result.toString();
+        }
+
+        private void appendEntries(StringBuilder result, String condition, EntryCondition predicate) {
+            List<InspectedEntry> matching = entries.stream()
+                    .filter(predicate::matches)
+                    .sorted(Comparator.comparing(entry -> entry.indexEntry.ruleDescription))
+                    .collect(toList());
+            if (matching.isEmpty()) {
+                return;
+            }
+            result.append("\n").append(condition).append(" entries:");
+            for (InspectedEntry entry : matching) {
+                result.append("\n  ").append(entry.indexEntry.ruleDescription)
+                        .append(" -> ").append(entry.indexEntry.fileName);
+            }
+        }
+    }
+
+    @FunctionalInterface
+    private interface EntryCondition {
+        boolean matches(InspectedEntry entry);
+    }
+
+    private static class FileSyncedProperties {
+        private final File propertiesFile;
+        private final Properties loadedProperties;
+
+        private FileSyncedProperties(File file) {
+            propertiesFile = file;
+            loadedProperties = loadRulesFrom(file);
+        }
+
+        private static Properties loadRulesFrom(File file) {
+            Properties result = new Properties();
+            if (!file.exists()) {
+                return result;
+            }
+            try (FileInputStream inputStream = new FileInputStream(file)) {
+                result.load(inputStream);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+            return result;
+        }
+
+        private List<IndexEntry> entries() {
+            List<IndexEntry> result = new ArrayList<>();
+            for (String key : loadedProperties.stringPropertyNames()) {
+                result.add(new IndexEntry(key, loadedProperties.getProperty(key)));
+            }
+            return result;
+        }
+
+        private IndexEntry find(String ruleDescription) {
+            String normalized = ensureUnixLineBreaks(ruleDescription);
+            if (loadedProperties.containsKey(normalized)) {
+                return new IndexEntry(normalized, loadedProperties.getProperty(normalized));
+            }
+            for (IndexEntry entry : entries()) {
+                if (ensureUnixLineBreaks(entry.ruleDescription).equals(normalized)) {
+                    return entry;
+                }
+            }
+            return null;
+        }
+
+        private Properties copy() {
+            Properties result = new Properties();
+            result.putAll(loadedProperties);
+            return result;
+        }
+
+        private void commit(Properties updated) {
+            syncFileSystem(updated);
+            loadedProperties.clear();
+            loadedProperties.putAll(updated);
+        }
+
+        private void createIfAbsent() {
+            if (propertiesFile.exists()) {
+                return;
+            }
+            try {
+                if (!propertiesFile.createNewFile() && !propertiesFile.isFile()) {
+                    throw new IOException("Could not create " + propertiesFile);
+                }
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+
+        private void syncFileSystem(Properties properties) {
+            File directory = propertiesFile.getParentFile();
+            Path temporary = null;
+            try {
+                temporary = Files.createTempFile(directory.toPath(), STORED_RULES_FILE_NAME, ".tmp");
+                try (OutputStream outputStream = new FileOutputStream(temporary.toFile())) {
+                    properties.store(outputStream, "");
+                }
+                try {
+                    Files.move(temporary, propertiesFile.toPath(), StandardCopyOption.ATOMIC_MOVE,
+                            StandardCopyOption.REPLACE_EXISTING);
+                } catch (AtomicMoveNotSupportedException e) {
+                    Files.move(temporary, propertiesFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
+                }
